// ============ ÉDITE CE NODE : C'EST TON BRIEF ============
return [{ json: {
  brief: {
    sujet: "L'IA locale pour les indépendants et PME : la souveraineté numérique sans datacenter",
    public: "Professionnels non-techniciens, dirigeants de petites structures, indépendants curieux d'IA",
    ton: "Pédagogue, direct, ancré dans la pratique. Posture d'apprenant curieux, jamais donneur de leçons.",
    nb_chapitres: 8,
    transformation: "Le lecteur sait décider quoi faire tourner en local, avec quel matériel, et par où commencer concrètement."
  },
  echantillon_style: `(aucun échantillon) COLLE ICI 2 À 3 PAGES DE TA PROPRE PROSE à la place de cette phrase. L'Éditeur imitera ce style. Tant que cette phrase est là, l'Éditeur se contente de fluidifier le texte.`
} }];

// ===== BODY POUR L'ARCHITECTE (gemma4:e4b, JSON forcé) =====
const b = $json.brief;

const system = `Tu es architecte éditorial. Tu conçois la structure complète d'un livre à partir d'un brief.

RÈGLES ABSOLUES :
1. Tu réponds UNIQUEMENT avec un objet JSON valide, sans texte avant ou après, sans balises markdown.
2. Le JSON respecte EXACTEMENT le schéma fourni. Aucun champ ajouté, aucun champ omis.
3. Le nombre de chapitres demandé est respecté. Chaque chapitre a un objectif UNIQUE et mesurable (le lecteur saura faire X ou comprendra Y).
4. Les points_cles sont 3 à 5 idées concrètes par chapitre, pas des généralités.
5. La these_centrale tient en une phrase : c'est l'argument que tout le livre défend.
6. La progression est logique : chaque chapitre s'appuie sur le précédent. Pas de doublon d'objectifs.
7. Tous les champs statut valent « a_faire », tous les resume_150_mots valent \"\" et decisions vaut [].
8. Langue : français.

SCHÉMA :
{
  \"meta\": {\"titre\": string, \"public_cible\": string, \"ton\": string, \"langue\": \"fr\", \"these_centrale\": string, \"interdits\": [string]},
  \"terminologie\": {},
  \"chapitres\": [{\"numero\": int, \"titre\": string, \"objectif\": string, \"points_cles\": [string], \"statut\": \"a_faire\", \"resume_150_mots\": \"\", \"decisions\": []}]
}`;

const prompt = `BRIEF DU LIVRE :\nSujet : ${b.sujet}\nPublic visé : ${b.public}\nTon souhaité : ${b.ton}\nNombre de chapitres : ${b.nb_chapitres}\nCe que le lecteur doit retirer : ${b.transformation}\n\nProduis le state.json complet.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  format: "json",
  options: { temperature: 0.4, num_ctx: 8192 }
} }];

// ===== PARSER LE PLAN + INITIALISER LA MÉMOIRE DU LIVRE =====
let brut = ($json.response || "").replace(/<think>[\s\S]*?<\/think>/g, "").trim();
const d = brut.indexOf("{");
const f = brut.lastIndexOf("}");
if (d === -1 || f <= d) {
  throw new Error("L'Architecte n'a pas produit de JSON. Début de sortie : " + brut.substring(0, 300));
}
const state = JSON.parse(brut.substring(d, f + 1));
if (!state.chapitres || !Array.isArray(state.chapitres) || state.chapitres.length === 0) {
  throw new Error("state.json invalide : aucun chapitre.");
}
if (!state.meta) state.meta = {};
if (!state.terminologie) state.terminologie = {};

// Mémoire d'exécution partagée entre tous les nodes
const mem = $getWorkflowStaticData('global');
mem.state = state;
mem.resumes = [];
mem.chapitres_valides = [];

// Un item par chapitre → alimente la boucle
return state.chapitres.map(ch => ({ json: { chapitre: ch } }));

// ===== BODY POUR LE RÉDACTEUR (gemma4:e4b) =====
// Reçoit soit l'Init (iteration 1), soit le GATE (reprise)
const ch = $json.chapitre;
const iteration = $json.iteration || 1;
const critiques = $json.critiques_eventuelles || "";

const mem = $getWorkflowStaticData('global');
const meta = mem.state.meta;
const term = mem.state.terminologie;
const resumes = mem.resumes.length ? mem.resumes.join("\n\n") : "(aucun — premier chapitre ou début du livre)";

const system = `Tu es écrivain professionnel. Tu rédiges UN chapitre de livre, en français, d'après un plan strict.

RÈGLES ABSOLUES :
1. Tu rédiges UNIQUEMENT le chapitre demandé. Pas d'introduction du type « Voici le chapitre », pas de commentaire méta. Ta réponse commence directement par le titre du chapitre en niveau markdown ## et continue en prose.
2. Tu couvres TOUS les points_cles du plan, dans un ordre logique, sans en ajouter d'autres.
3. Tu respectes la these_centrale et le ton définis. Tu n'utilises jamais les éléments listés dans les interdits.
4. Tu utilises la terminologie EXACTEMENT comme définie dans le glossaire. Tout terme technique nouveau est défini à sa première occurrence.
5. Cohérence : tu ne répètes pas ce que les résumés des chapitres précédents indiquent comme déjà traité. Référence brève autorisée (« comme vu au chapitre 3 »).
6. Longueur : entre 1500 et 2500 mots.
7. Structure : prose fluide dominante. Maximum 2 listes à puces dans tout le chapitre. Sous-titres (###) toutes les 400-600 mots.
8. Chaque affirmation chiffrée ou factuelle précise est marquée [VERIF] juste après.
9. Tu écris uniquement en français : aucun mot ou caractère d'une autre langue.
10. SI des critiques te sont fournies (mode reprise) : tu réécris le chapitre en corrigeant CHAQUE point critiqué, sans retouches cosmétiques.`;

const prompt = `CONTEXTE DU LIVRE :\nThèse centrale : ${meta.these_centrale}\nTon : ${meta.ton}\nPublic : ${meta.public_cible}\nInterdits : ${(meta.interdits || []).join(", ")}\nTerminologie : ${JSON.stringify(term)}\n\nRÉSUMÉS DES CHAPITRES PRÉCÉDENTS :\n${resumes}\n\nPLAN DU CHAPITRE À RÉDIGER :\nNuméro : ${ch.numero}\nTitre : ${ch.titre}\nObjectif : ${ch.objectif}\nPoints clés à couvrir :\n${ch.points_cles.map((p, i) => (i + 1) + ". " + p).join("\n")}\n\n${critiques ? "CRITIQUES À CORRIGER (mode reprise) :\n" + critiques + "\n\n" : ""}Rédige le chapitre.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  options: { temperature: 0.8, num_ctx: 16384 },
  _iteration: iteration
} }];

// ===== BODY POUR LE CRITIQUE (deepseek-r1:7b, JSON forcé) =====
const texteChapitre = $json.response;
const mem = $getWorkflowStaticData('global');
const meta = mem.state.meta;
const ch = $('Init chapitre').first().json.chapitre;
const resumes = mem.resumes.length ? mem.resumes.join("\n\n") : "(aucun)";

const system = `Tu es un critique littéraire et éditorial impitoyable mais juste. Tu évalues UN chapitre contre son plan.

RÈGLES ABSOLUES :
1. Tu réponds UNIQUEMENT avec un objet JSON valide conforme au schéma. Aucun texte hors JSON.
2. Tu notes chaque axe de 1 à 10. Un 8+ signifie « publiable tel quel sur cet axe ». Sois sévère : la moyenne attendue d'un premier jet est 6.
3. Pour passages_faibles, tu cites EXACTEMENT 3 extraits textuels (10-30 mots chacun, copiés mot pour mot du chapitre) avec la raison précise de leur faiblesse. Obligatoire même si le chapitre est bon.
4. couverture_plan : tu listes chaque point_cle du plan avec true/false selon qu'il est réellement traité (pas juste mentionné).
5. Tu ne proposes PAS de réécriture. Tu diagnostiques.
6. Tu écris uniquement en français.

SCHÉMA :
{
  \"scores\": {\"clarte\": int, \"tenue_objectif\": int, \"non_redondance\": int, \"respect_ton\": int, \"densite_valeur\": int},
  \"couverture_plan\": [{\"point_cle\": string, \"couvert\": boolean}],
  \"passages_faibles\": [{\"extrait\": string, \"probleme\": string}],
  \"verdict_une_phrase\": string
}`;

const prompt = `PLAN DU CHAPITRE :\nObjectif : ${ch.objectif}\nPoints clés attendus :\n${ch.points_cles.map((p, i) => (i + 1) + ". " + p).join("\n")}\nTon attendu : ${meta.ton}\n\nRÉSUMÉS DES CHAPITRES PRÉCÉDENTS (pour juger la redondance) :\n${resumes}\n\nCHAPITRE À ÉVALUER :\n${texteChapitre}\n\nÉvalue.`;

return [{ json: {
  model: "deepseek-r1:7b",
  system,
  prompt,
  stream: false,
  format: "json",
  options: { temperature: 0.2, num_ctx: 16384 },
  _texte_chapitre: texteChapitre
} }];

// ===== GATE DÉTERMINISTE v3 — blindé + reprise automatique =====
let brut = ($json.response || "");
brut = brut.replace(/<think>[\s\S]*?<\/think>/g, "").trim();

let evaluation = null;
const d = brut.indexOf("{");
const f = brut.lastIndexOf("}");
if (d !== -1 && f > d) {
  try { evaluation = JSON.parse(brut.substring(d, f + 1)); } catch (e) {}
}

const ch = $('Init chapitre').first().json.chapitre;
const iteration = $('Préparer requête Rédacteur').first().json._iteration || 1;
const texteChapitre = $('Préparer requête Critique').first().json._texte_chapitre;
const MAX_ITERATIONS = 2;

const schemaOK = evaluation && evaluation.scores && typeof evaluation.scores === "object" && Object.keys(evaluation.scores).length >= 3;

// Si le Critique déraille : on valide avec réserve technique plutôt que de bloquer le livre
if (!schemaOK) {
  return [{ json: {
    decision: "valide_avec_reserves",
    moyenne: null, min_score: null, plan_complet: null,
    iteration, chapitre: ch,
    alertes: ["Critique illisible : chapitre validé sans évaluation. Sortie brute : " + brut.substring(0, 300)],
    verdict: "", reserves: [],
    texte_chapitre: texteChapitre
  } }];
}

const scores = Object.values(evaluation.scores).filter(v => typeof v === "number");
const moyenne = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10;
const minScore = Math.min(...scores);
const planComplet = (evaluation.couverture_plan || []).every(p => p.couvert);

// Contrôles déterministes
const nbMots = texteChapitre.split(/\s+/).length;
const nbPuces = (texteChapitre.match(/^\s*[\*\-]\s+/gm) || []).length;
const anneesSuspectes = texteChapitre.match(/\b20(1[0-9]|2[0-4])\b/g) || [];
const caracteresCJK = /[\u4e00-\u9fff]/.test(texteChapitre);
const alertes = [];
if (nbMots < 1400 || nbMots > 2700) alertes.push("Longueur hors cible : " + nbMots + " mots");
if (nbPuces > 8) alertes.push("Trop de puces : " + nbPuces + " lignes");
if (anneesSuspectes.length) alertes.push("Années à vérifier : " + [...new Set(anneesSuspectes)].join(", "));
if (caracteresCJK) alertes.push("Caractères chinois détectés dans le texte");

const VALIDE = moyenne >= 8 && minScore >= 5 && planComplet && !caracteresCJK;

if (VALIDE || iteration >= MAX_ITERATIONS) {
  return [{ json: {
    decision: VALIDE ? "valide" : "valide_avec_reserves",
    moyenne, min_score: minScore, plan_complet: planComplet,
    iteration, chapitre: ch, nb_mots: nbMots, alertes,
    verdict: evaluation.verdict_une_phrase || "",
    reserves: VALIDE ? [] : (evaluation.passages_faibles || []),
    texte_chapitre: texteChapitre
  } }];
}

// Reprise automatique
const critiques = [
  "Verdict : " + (evaluation.verdict_une_phrase || ""),
  ...(evaluation.couverture_plan || []).filter(p => !p.couvert).map(p => "Point non traité : " + p.point_cle),
  ...(evaluation.passages_faibles || []).map(p => "Passage faible : « " + p.extrait + " » → " + (p.probleme || p["problème"] || "")),
  ...alertes.map(a => "Contrôle automatique : " + a)
].join("\n");

return [{ json: {
  decision: "reprise",
  moyenne, min_score: minScore, plan_complet: planComplet,
  iteration: iteration + 1,
  chapitre: ch,
  critiques_eventuelles: critiques,
  texte_chapitre: texteChapitre
} }];

// ===== BODY POUR L'ÉDITEUR (gemma4:e4b) — alignement stylistique =====
const texte = $json.texte_chapitre;
const echantillon = $('Brief du livre').first().json.echantillon_style;

const system = `Tu es éditeur littéraire. Tu réécris un chapitre pour l'aligner sur le style d'un ÉCHANTILLON DE RÉFÉRENCE, sans changer le fond.

RÈGLES ABSOLUES :
1. Ta réponse est UNIQUEMENT le chapitre réécrit, du titre ## à la dernière phrase. Aucun commentaire.
2. Le FOND est intouchable : mêmes idées, mêmes arguments, même ordre, mêmes faits, mêmes marqueurs [VERIF] conservés à l'identique. Tu ne coupes aucune idée, tu n'en ajoutes aucune.
3. La FORME s'aligne sur l'échantillon : longueur des phrases, rythme, niveau de langue, usage des questions, façon d'ouvrir et fermer les paragraphes.
4. Tu élimines : répétitions de mots à moins de 3 phrases d'écart, passives évitables, adverbes creux, phrases de plus de 35 mots (à découper).
5. Tu améliores les transitions entre sous-parties.
6. Longueur finale : entre -10% et +5% du texte d'origine.
7. Tu écris uniquement en français.`;

const prompt = `ÉCHANTILLON DE RÉFÉRENCE STYLISTIQUE (prose de l'auteur, à imiter) :\n${echantillon}\n\nCHAPITRE À RÉÉCRIRE :\n${texte}\n\nRéécris.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  options: { temperature: 0.5, num_ctx: 16384 }
} }];

// ===== BODY POUR LE RÉSUMÉ (mistral:7b, JSON forcé) =====
const texteFinal = $json.response;

const system = `Tu résumes un chapitre de livre en 150 mots maximum, en français, pour servir de mémoire aux chapitres suivants.

RÈGLES :
1. Sortie UNIQUEMENT en JSON : {\"resume_150_mots\": string, \"decisions\": [string]}
2. Le résumé liste ce qui a été TRAITÉ (concepts définis, exemples utilisés, conclusions posées) — pas un teaser.
3. decisions liste les choix engageants pour la suite : termes définis, positions prises, promesses faites au lecteur. Maximum 5.`;

const prompt = `CHAPITRE :\n${texteFinal}\n\nRésume.`;

return [{ json: {
  model: "mistral:7b",
  system,
  prompt,
  stream: false,
  format: "json",
  options: { temperature: 0.2, num_ctx: 16384 }
} }];

// ===== METTRE À JOUR LA MÉMOIRE DU LIVRE + ARCHIVER LE CHAPITRE =====
let brut = ($json.response || "").replace(/<think>[\s\S]*?<\/think>/g, "").trim();
let resume = { resume_150_mots: "(résumé indisponible)", decisions: [] };
const d = brut.indexOf("{");
const f = brut.lastIndexOf("}");
if (d !== -1 && f > d) {
  try { resume = JSON.parse(brut.substring(d, f + 1)); } catch (e) {}
}

const mem = $getWorkflowStaticData('global');
const ch = $('Init chapitre').first().json.chapitre;
const texteFinal = $('Ollama — ÉDITEUR').first().json.response;
const infosGate = $('GATE (validation déterministe)').first().json;

mem.resumes.push("Chapitre " + ch.numero + " (" + ch.titre + ") : " + (resume.resume_150_mots || "") + (resume.decisions && resume.decisions.length ? " | Décisions : " + resume.decisions.join(" ; ") : ""));
mem.chapitres_valides.push({
  numero: ch.numero,
  titre: ch.titre,
  texte: texteFinal,
  decision: infosGate.decision,
  moyenne: infosGate.moyenne,
  alertes: infosGate.alertes || []
});

return [{ json: { chapitre_termine: ch.numero, titre: ch.titre, decision: infosGate.decision } }];

// ===== ASSEMBLAGE FINAL DU MANUSCRIT =====
const mem = $getWorkflowStaticData('global');
const state = mem.state;
const chapitres = (mem.chapitres_valides || []).sort((a, b) => a.numero - b.numero);

const entete = [
  "# " + (state.meta.titre || "Manuscrit"),
  "",
  "> Généré par l'Atelier Écriture — " + new Date().toLocaleDateString("fr-FR"),
  "> Thèse centrale : " + (state.meta.these_centrale || ""),
  "",
  "---",
  ""
].join("\n");

const corps = chapitres.map(c => c.texte).join("\n\n---\n\n");

// Rapport de production en fin de fichier
const rapport = [
  "\n\n---\n\n## Rapport de production (à supprimer avant publication)\n",
  ...chapitres.map(c => "- Chapitre " + c.numero + " (" + c.titre + ") : " + c.decision + (c.moyenne !== null && c.moyenne !== undefined ? ", moyenne " + c.moyenne : "") + (c.alertes.length ? " — ALERTES : " + c.alertes.join(" | ") : ""))
].join("\n");

const texte = entete + corps + rapport;
const dateStr = new Date().toISOString().slice(0, 10);
const fileName = "/home/node/sorties/livre-" + dateStr + ".md";

return [{ json: { texte, fileName, nb_chapitres: chapitres.length } }];
